        private static System.Net.Http.HttpClient CreateHttpClient()
        {
            var client = new System.Net.Http.HttpClient { Timeout = TimeSpan.FromSeconds(12) };
            client.DefaultRequestHeaders.UserAgent.ParseAdd("DFP-Pro-Launcher/1.0");
