        {
            ApplyFilter();
            RefreshDashboard();
            RebuildStaticTiles();
            RefreshApps();
            RefreshBoard();
            RenderDeals();
            UpdateClock();
            UpdateSliderLabels();
            RebuildTrayMenu();
            BuildSchemeTiles();
            BuildDashWidgetSettings();
            RenderWishlist();
            ApplyUpdateUi();
            UpdatePlanTiles(currentPowerPlanName);
            if (ViewOptimization.Visibility == Visibility.Visible)
            {
                RenderCleanup();
                _ = MeasureCleanupAsync();
