        private Dictionary<string, System.Windows.Controls.RadioButton> NavButtonMap() => new()
        {
            ["dashboard"] = NavDashboardBtn,
            ["games"] = NavGamesBtn,
            ["stats"] = NavStatsBtn,
            ["deals"] = NavDealsBtn,
            ["backlog"] = NavBacklogBtn,
            ["gallery"] = NavGalleryBtn,
            ["apps"] = NavAppsBtn,
            ["links"] = NavLinksBtn,
            ["wishlist"] = NavWishBtn,
            ["downloads"] = NavDownloadsBtn,
