                if (konamiPadIndex == KonamiPad.Length)
                {
                    konamiPadIndex = 0;
                    TriggerKonami();
                }
            }
            else
            {
                konamiPadIndex = pressed == KonamiPad[0] ? 1 : 0;
            }
        }

