        private string? PickGreeting(out bool rare)
        {
            rare = false;
            if (!EggsOn) return null;

            if (IsCreatorName(DisplayUserName())) return Loc.T("Der Creator persönlich");

            if (random.Next(50) == 0)
            {
                rare = true;
                return Loc.T(RareGreetings[random.Next(RareGreetings.Length)]);
            }
            return null;
